    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    int ret;
    int state = 0;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the lines for GPIO 2 and GPIO 3
    line2 = gpiod_chip_get_line(chip, 2);
    line3 = gpiod_chip_get_line(chip, 3);
    if (!line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the lines as output
    ret = gpiod_line_request_output(line2, "gpio2_control", state, GPIOD_LINE_REQUEST_DIRECTIONS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO 2 as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line3, "gpio3_control", state, GPIOD_LINE_REQUEST_DIRECTIONS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO 3 as output\n");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Toggle the state
        state = !state;

        // Set the state on both lines
        ret = gpiod_line_set_value(line2, state);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 2 value\n");
