#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    char *i2c_device = "/dev/i2c-1";
    uint16_t config;
    uint16_t data;
    int res;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
             ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
             ADS1115_CONFIG_DR_128SPS;

    // Write configuration to ADS1115
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write configuration to ADS1115");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read conversion result
        if (write(i2c_fd, &ADS1115_REG_POINTER_CONVERT, 1) != 1) {
            perror("Failed to set pointer to conversion register");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        if (read(i2c_fd, &data, 2) != 2) {
            perror("Failed to read conversion result");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Convert the data to voltage
        int16_t raw = (data & 0x0FFF) << 4;
        if (data & 0x8000) {
            raw |= 0xF000;
        }
        float voltage = raw * 0.1875 / 1000.0; // 6.144V range, 16-bit

        printf("Voltage: %.3f V\n", voltage);

        // Wait for 0.5 seconds
        usleep(500000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

