#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define MLX90614_EMISSIVITY 0.95
#define MLX90614_TOBJ1 0x07
#define MLX90614_TOBJ2 0x06

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

float read_temperature(int fd) {
    unsigned char buffer[3];
    int bytes_read;

    // Read the raw temperature data
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    buffer[0] = MLX90614_TOBJ1;
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    bytes_read = read(fd, buffer, 3);
    if (bytes_read != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert the raw data to temperature
    int raw_temp = (buffer[1] << 8) | buffer[2];
    float temp = raw_temp * 0.02 - 273.15; // Convert to Celsius

    return temp;
}

int main() {
    int i2c_fd;
    float temperature;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if the device is present
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        close(i2c_fd);
        fprintf(stderr, "MLX90614 not found at address 0x%02X\n", I2C_ADDRESS);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        temperature = read_temperature(i2c_fd);
        if (temperature < 0) {
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        printf("Temperature: %.2f°C\n", temperature);
        sleep(5);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

