    line4 = gpiod_chip_get_line(chip, 4);
    if (!line4) {
        perror("gpiod_chip_get_line for GPIO 4");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, 17);
    if (!line17) {
        perror("gpiod_chip_get_line for GPIO 17");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the lines as output
    ret = gpiod_line_request_output(line4, "gpio4_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output for GPIO 4");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line17, "gpio17_output", 1);
    if (ret < 0) {
