    if (result != 2) {
        perror("Failed to write configuration to ADS1115");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Start conversion
        config[1] |= ADS1115_CONFIG_OS_SINGLE;
        result = write(i2c_fd, config, 2);
        if (result != 2) {
            perror("Failed to start conversion");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for conversion to complete
        usleep(100000); // 100ms

        // Read conversion result
        result = read(i2c_fd, data, 2);
        if (result != 2) {
            perror("Failed to read conversion result");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Convert data to 16-bit integer
        reading = (data[0] << 8) | data[1];
        if (reading & 0x8000) {
            reading |= 0xFFFF0000; // Sign extend negative values
        }

        // Print reading
        printf("Reading: %d\n", reading);

        // Delay for 0.1 seconds
        usleep(100000);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

