#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 512 // 50% duty cycle

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(GPIO_PIN, PWM_FREQUENCY, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set PWM: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        printf("PWM applied: Frequency = %d Hz, Duty Cycle = %d\n", PWM_FREQUENCY, PWM_DUTY_CYCLE);
        sleep(0.5);
    }

    gpioPWM(GPIO_PIN, 0, 0); // Stop PWM
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define MAX_DISTANCE_CM 400
#define MAX_DISTANCE_US (MAX_DISTANCE_CM * 58) // 1 cm = 58us

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    struct gpiod_line_event event;
    struct timespec ts_start, ts_end;
    long duration_us;
    double distance_cm;

    // Trigger the sensor
    gpiod_line_set_value(trig, 1);
    nanosleep((const struct timespec[]){{0, 10 * 1000 * 1000}}, NULL); // 10us
    gpiod_line_set_value(trig, 0);

    // Wait for echo start
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_RISING, 1000 * 1000) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        fprintf(stderr, "Failed to read echo start event\n");
        return -1;
    }
    ts_start = event.ts;

    // Wait for echo end
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_FALLING, 1000 * 1000) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        fprintf(stderr, "Failed to read echo end event\n");
        return -1;
    }
    ts_end = event.ts;

    // Calculate duration
    duration_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000;
    if (duration_us > MAX_DISTANCE_US) {
        fprintf(stderr, "Distance out of range\n");
        return -1;
    }

    // Calculate distance
    distance_cm = duration_us / 58.0;
    return distance_cm;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    double distance_cm;

    // Setup signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
