#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    char filename[20];

    snprintf(filename, sizeof(filename), "/dev/i2c-%s", device);
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }

    return file;
}

int read_adc(int file) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS;
    uint16_t conversion;

    if (write(file, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion to complete

    if (read(file, &conversion, sizeof(conversion)) != sizeof(conversion)) {
        perror("Failed to read conversion result from ADS1115");
        return -1;
    }

    // Check if the conversion is valid (OS bit is cleared)
    if (conversion & ADS1115_CONFIG_OS_SINGLE) {
        fprintf(stderr, "Invalid conversion result\n");
        return -1;
    }

    return conversion;
}

int main() {
    int file;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        return EXIT_FAILURE;
    }

    file = open_i2c_device("1", ADS1115_ADDRESS);
    if (file < 0) {
        fprintf(stderr, "ADS1115 not found at address 0x%02X\n", ADS1115_ADDRESS);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int conversion = read_adc(file);
        if (conversion >= 0) {
            printf("ADC Reading: %d\n", conversion);
        }
        sleep(5);
    }

    close(file);
    return EXIT_SUCCESS;
}

