    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO 18\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as a digital output
    ret = gpiod_line_request_output(line, "gpio18_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Perform the cycles
