        // Set the line high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line high\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
