        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Send measurement command
        buffer[0] = SI7021_MEASURE_RELATIVE_HUMIDITY_HOLD_MASTER_MODE;
        ret = write(i2c_fd, buffer, 1);
        if (ret != 1) {
            perror("Failed to write to I2C device");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for measurement to complete
        usleep(100000); // 100 ms

        // Read measurement result
        ret = read(i2c_fd, buffer, 2);
        if (ret != 2) {
