        uint8_t crc = buffer[0] + buffer[1];
        if ((crc & 0xFF) != 0) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        // Convert to 16-bit value
        raw_humidity = (buffer[0] << 8) | buffer[1];

        // Calculate relative humidity
        humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

        // Print humidity
        printf("Humidity: %.2f%%\n", humidity);

        // Wait for 5 seconds
        sleep(5);
    }

