#define TIMEOUT_NS 1000000000 // 1 second in nanoseconds

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    struct gpiod_line_event event;
    struct gpiod_line_request req;
    struct gpiod_line_event_data data;
    struct timespec start, end;
    long duration_ns;
    double distance_cm;

    // Trigger the sensor
    gpiod_line_set_value(trig, 1);
    nanosleep((const struct timespec[]){{0, 10 * 1000 * 1000}}, NULL); // 10us
    gpiod_line_set_value(trig, 0);

    // Wait for echo start
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_RISING, TIMEOUT_NS, &event) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }
    gpiod_line_event_get_data(&event, &data);
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo end
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_FALLING, TIMEOUT_NS, &event) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    gpiod_line_event_get_data(&event, &data);
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate duration
    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);

    // Calculate distance
    distance_cm = (duration_ns / 2.0) * 0.0343;

    return distance_cm;
}

