    struct gpiod_line *trig, *echo;
    struct gpiod_line_request req;
    double distance_cm;

    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0 ||
        gpiod_line_request_input(echo, "echo", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        distance_cm = measure_distance(chip, trig, echo);
        if (distance_cm < 0) {
            fprintf(stderr, "Error measuring distance\n");
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
        }
        sleep(1);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

