#define DHT11_GPIO 4
#define DHT11_PIN 4
#define DHT11_MAX_RETRIES 5
#define DHT11_TIMEOUT_USEC 1000000

volatile sig_atomic_t interrupted = 0;

void handle_signal(int sig) {
    interrupted = 1;
}

int read_dht11(gpiod_line_handle_t line, uint8_t *humidity, uint8_t *temperature) {
    uint64_t data[5] = {0};
    uint8_t bits[5] = {0};
    int retries = 0;
    int ret;

    // Set GPIO to output and low
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    usleep(18000); // 18ms

    // Set GPIO to input
    ret = gpiod_line_request_rising_edge_events(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request rising edge events: %s\n", strerror(-ret));
        return -1;
    }

    // Wait for the DHT11 response
    ret = gpiod_line_event_wait(line, DHT11_TIMEOUT_USEC);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for DHT11 response\n");
        return -1;
    }

    // Read 40 bits (5 bytes) from DHT11
    for (int i = 0; i < 5; i++) {
        uint64_t bit_count = 0;
        uint64_t timeout = DHT11_TIMEOUT_USEC / 2;

        // Wait for the pin to go low
        ret = gpiod_line_event_wait(line, timeout);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for low signal\n");
            return -1;
        }

        // Count the length of the high pulse
        while (gpiod_line_get_value(line) && !interrupted) {
            usleep(1);
            bit_count++;
            if (bit_count > DHT11_TIMEOUT_USEC) {
                fprintf(stderr, "Timeout waiting for high signal\n");
                return -1;
            }
        }

        if (interrupted) {
            fprintf(stderr, "Interrupted\n");
            return -1;
        }

        bits[i] = bit_count > 50 ? 1 : 0;
    }

    // Convert bits to bytes
    for (int i = 0; i < 5; i++) {
        data[i] = 0;
        for (int j = 0; j < 8; j++) {
            data[i] <<= 1;
            data[i] |= bits[i * 8 + (7 - j)];
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    gpiod_line_handle_t line_handle;
    uint8_t humidity, temperature;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get line for GPIO 4
    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", DHT11_GPIO);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    line_handle = gpiod_line_request(line, "dht11_reader", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH);
    if (!line_handle) {
        fprintf(stderr, "Failed to request line: %s\n", gpiod_strerror(gpiod_line_get_error(line)));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Attempt to read from DHT11
    while (retries < DHT11_MAX_RETRIES) {
        ret = read_dht11(line_handle, &humidity, &temperature);
        if (ret == 0) {
            printf("Humidity: %d%%, Temperature: %d°C\n", humidity, temperature);
            break;
        }
        retries++;
        fprintf(stderr, "Retrying... (%d/%d)\n", retries, DHT11_MAX_RETRIES);
    }

    if (retries == DHT11_MAX_RETRIES) {
        fprintf(stderr, "Failed to read from DHT11 after %d retries\n", DHT11_MAX_RETRIES);
        ret = EXIT_FAILURE;
    } else {
        ret = EXIT_SUCCESS;
    }

    // Release resources
    gpiod_line_release(line_handle);
    gpiod_chip_close(chip);

    return ret;
}

