#define I2C_DEVICE "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define OPT3001_REG 0x00

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    uint8_t buffer[2];
    uint16_t measurement;
    int result;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read measurement from OPT3001
    while (keep_running) {
        result = read(i2c_fd, buffer, 2);
        if (result < 0) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            return EXIT_FAILURE;
        } else if (result != 2) {
            fprintf(stderr, "Unexpected read size: %d\n", result);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Convert the two bytes to a 16-bit measurement
        measurement = (buffer[0] << 8) | buffer[1];

        // Print the measurement
        printf("Measurement: %u\n", measurement);

        // Exit after one successful read
        break;
    }

    // Close the I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

