#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0

volatile sig_atomic_t interrupted = 0;

void handle_signal(int sig) {
    interrupted = 1;
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART device");
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof tty);

    if (tcgetattr(fd, &tty) != 0) {
        perror("Error from tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // disable break processing
    tty.c_lflag = 0;                                // no signaling chars, no echo,
    tty.c_oflag = 0;                                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;                            // read doesn't block
    tty.c_cc[VTIME] = 1;                            // 0.1 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // shut off xon/xoff ctrl
    tty.c_cflag |= (CLOCAL | CREAD);                // ignore modem controls,
                                                    // enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error from tcsetattr");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, handle_signal);

    int uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    struct timeval timeout;
    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;
    if (setsockopt(uart_fd, SOL_SOCKET, SO_RCVTIMEO, (const char*)&timeout, sizeof(timeout)) < 0) {
        perror("Error setting socket receive timeout");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    char buffer[256];
    ssize_t bytes_read;

    while ((bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0';
        printf("Received: %s\n", buffer);
        break; // Run once and exit
    }

    if (bytes_read < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
        perror("Error reading from UART");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    if (interrupted) {
        printf("Program interrupted by signal\n");
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

