    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO 2\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as a consumer
    ret = gpiod_line_request_output(line, "gpio_control", 0);
