    int fd = open(temp_path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open temperature file");
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("Failed to read temperature data");
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';

    close(fd);

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "Failed to read valid temperature data\n");
        return -1;
    }

    char *crc_check = strstr(buffer, "crc=");
    if (crc_check == NULL) {
        fprintf(stderr, "Failed to find CRC check in data\n");
        return -1;
    }

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Failed to find temperature data\n");
        return -1;
    }

    temp_str += 2; // Skip "t="

    char *endptr;
    long temp = strtol(temp_str, &endptr, 10);
    if (endptr == temp_str || *endptr != '\0') {
