#define HTU21D_ADDRESS 0x40
#define HTU21D_MEASURE_TEMP_CMD 0xE3
#define HTU21D_MEASURE_HUM_CMD 0xE5
#define HTU21D_READ_STATUS_CMD 0xF3
#define HTU21D_RESET_CMD 0xFE

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_i2c_byte(int file, uint8_t cmd) {
    uint8_t buffer[1] = {cmd};
    if (write(file, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(file, buffer, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return buffer[0];
}

int read_i2c_word(int file, uint8_t cmd) {
    uint8_t buffer[3] = {cmd, 0, 0};
    if (write(file, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(file, buffer + 1, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (buffer[2] << 8) | buffer[1];
}

int check_status(int file) {
    int status = read_i2c_byte(file, HTU21D_READ_STATUS_CMD);
    if (status < 0) {
        return -1;
    }
    return (status & 0x01) == 0;
}

int read_temperature(int file) {
    if (check_status(file) < 0) {
        return -1;
    }

    int raw = read_i2c_word(file, HTU21D_MEASURE_TEMP_CMD);
    if (raw < 0) {
        return -1;
    }

    int temp = (175.72 * raw) / 65536.0 - 46.85;
    return temp;
}

int read_humidity(int file) {
    if (check_status(file) < 0) {
        return -1;
    }

    int raw = read_i2c_word(file, HTU21D_MEASURE_HUM_CMD);
    if (raw < 0) {
        return -1;
    }

    int humidity = (125.0 * raw) / 65536.0 - 6.0;
    return humidity;
}

