#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_BW_RATE_100HZ 0x0A
#define ADXL345_POWER_CTL_MEASURE 0x08

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        exit(1);
    }
    return file;
}

void configure_adxl345(int file) {
    uint8_t data;

    // Set data rate to 100 Hz
    data = ADXL345_BW_RATE_100HZ;
    if (write(file, &data, 1) != 1) {
        perror("Failed to write to ADXL345");
        close(file);
        exit(1);
    }

    // Set power control to measure mode
    data = ADXL345_POWER_CTL_MEASURE;
    if (write(file, &data, 1) != 1) {
        perror("Failed to write to ADXL345");
        close(file);
        exit(1);
    }
}

void read_adxl345(int file, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(file, buffer, 6) != 6) {
        perror("Failed to read from ADXL345");
        close(file);
        exit(1);
    }

    *x = (int16_t)(buffer[1] << 8 | buffer[0]);
    *y = (int16_t)(buffer[3] << 8 | buffer[2]);
    *z = (int16_t)(buffer[5] << 8 | buffer[4]);
}

int main() {
    int file;
    int16_t x, y, z;

    // Register signal handler
    signal(SIGINT, handle_signal);

    // Open I2C device
    file = open_i2c_device(I2C_DEVICE, ADXL345_ADDRESS);
    configure_adxl345(file);

    while (keep_running) {
        read_adxl345(file, &x, &y, &z);
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        usleep(100000); // Sleep for 0.1 seconds
    }

    // Clean up
    close(file);
    return 0;
}

