void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_GPIO; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    for (int i = 0; i < NUM_GPIO; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void toggle_gpio() {
    for (int i = 0; i < NUM_GPIO; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (gpiod_line_set_value(lines[i], !value) < 0) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PINS[i]);
        } else {
            printf("GPIO %d set to %d\n", GPIO_PINS[i], !value);
        }
    }
}

int main() {
    setup_gpio();

    signal(SIGINT, handle_signal);

    while (running) {
        toggle_gpio();
        nanosleep((const struct timespec[]){{0, INTERVAL}}, NULL);
    }

    cleanup_gpio();
    return 0;
}

