#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_tcs34725(int file, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buffer[8];
    buffer[0] = 0x14; // Command to read data

    if (write(file, buffer, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    if (read(file, buffer, 8) != 8) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    *clear = (buffer[0] << 8) | buffer[1];
    *red = (buffer[2] << 8) | buffer[3];
    *green = (buffer[4] << 8) | buffer[5];
    *blue = (buffer[6] << 8) | buffer[7];

    return 0;
}

int main() {
    int file;
    uint16_t red, green, blue, clear;

    signal(SIGINT, handle_signal);

    file = open_i2c_device(I2C_DEVICE, TCS34725_ADDRESS);
    if (file < 0) {
        fprintf(stderr, "Error: TCS34725 not found\n");
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_tcs34725(file, &red, &green, &blue, &clear) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading from TCS34725\n");
        }
        usleep(200000); // Sleep for 0.2 seconds
    }

    close(file);
    return EXIT_SUCCESS;
}

