#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_MJPEG
#define BUFFER_COUNT 4

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[BUFFER_COUNT];
    unsigned int i;
    int buffer_size;
    FILE *output_file;

    signal(SIGINT, signal_handler);

    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    buffer_size = fmt.fmt.pix.sizeimage;

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < BUFFER_COUNT; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (MAP_FAILED == buffers[i]) {
            perror("Failed to mmap buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < BUFFER_COUNT; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start capture");
        close(fd);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    ts.tv_sec = 5;
    ts.tv_nsec = 0;

    int ret = 0;
    for (i = 0; i < BUFFER_COUNT && !stop; ++i) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        ret = select(fd + 1, &fds, NULL, NULL, &ts);
        if (ret == -1) {
            perror("Select error");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                fprintf(stderr, "EAGAIN error\n");
                break;
            } else {
                perror("Failed to dequeue buffer");
                break;
            }
        }

        if (buf.index >= BUFFER_COUNT) {
            fprintf(stderr, "Buffer index out of range\n");
            break;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            break;
        }

        output_file = fopen("capture.jpg", "wb");
        if (!output_file) {
            perror("Failed to open output file");
            break;
        }

        if (fwrite(buffers[buf.index], 1, buf.bytesused, output_file) != buf.bytesused) {
            perror("Failed to write to output file");
            fclose(output_file);
            break;
        }

        fclose(output_file);
    }

    enum v4l2_buf_type type_stop = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type_stop) < 0) {
        perror("Failed to stop capture");
    }

    for (i = 0; i < BUFFER_COUNT; ++i) {
        if (munmap(buffers[i], buf.length) < 0) {
            perror("Failed to unmap buffer");
        }
    }

    close(fd);
    return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

