    // Set display clock divide ratio/oscillator frequency
    i2c_write_byte(file, 0x00, 0xC8);

    // Set multiplex ratio
    i2c_write_byte(file, 0x00, 0xA8);
    i2c_write_byte(file, 0x00, 0x3F);

    // Set display offset
