    i2c_write_byte(file, 0x00, 0xD9);
    i2c_write_byte(file, 0x00, 0xF1);

    // Set pre-charge period
    i2c_write_byte(file, 0x00, 0xDA);
    i2c_write_byte(file, 0x00, 0x12);

    // Set VCOMH deselect level
    i2c_write_byte(file, 0x00, 0xDB);
    i2c_write_byte(file, 0x00, 0x40);

