double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct gpiod_line_event event;
    struct timespec start, end;
    long pulse_duration;
    double distance;

    // Trigger the sensor
    gpiod_line_set_value(trig, 1);
    nanosleep((const struct timespec[]){{0, 10 * 1000 * 1000}}, NULL); // 10us
    gpiod_line_set_value(trig, 0);

    // Wait for echo start
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_USEC) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        fprintf(stderr, "Failed to read echo start event\n");
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo end
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_FALLING_EDGE, TIMEOUT_USEC) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        fprintf(stderr, "Failed to read echo end event\n");
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse duration
    pulse_duration = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    distance = pulse_duration / 58.0; // Convert to cm

