#define I2C_DEVICE "/dev/i2c-1"
#define BME280_I2C_ADDR 0x76
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_HUM_MSB 0xFD

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_i2c_byte(int file, uint8_t reg) {
    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    uint8_t data;
    if (read(file, &data, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return data;
}

int read_measurement(int file, uint8_t reg, int *value) {
    uint8_t msb = read_i2c_byte(file, reg);
    if (msb < 0) return -1;

    uint8_t lsb = read_i2c_byte(file, reg + 1);
    if (lsb < 0) return -1;

    uint8_t xlsb = read_i2c_byte(file, reg + 2);
    if (xlsb < 0) return -1;

    *value = ((int)msb << 16) | ((int)lsb << 8) | xlsb;
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);

    int file = open(I2C_DEVICE, O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int temp, press, hum;

        if (read_measurement(file, BME280_REG_TEMP_MSB, &temp) < 0 ||
            read_measurement(file, BME280_REG_PRESS_MSB, &press) < 0 ||
            read_measurement(file, BME280_REG_HUM_MSB, &hum) < 0) {
            fprintf(stderr, "Error reading from BME280\n");
            close(file);
            return EXIT_FAILURE;
        }

        printf("Temperature: %d\n", temp);
        printf("Pressure: %d\n", press);
        printf("Humidity: %d\n", hum);

        sleep(5);
    }

    close(file);
    return EXIT_SUCCESS;
}

