#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    unsigned char config[2];
    unsigned char data[2];
    int16_t reading;
    struct sigaction sa;

    // Set up signal handler for clean exit
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
                ADS1115_CONFIG_DR_128SPS;
    if (write(i2c_fd, config, 2) != 2) {
        perror("Failed to write configuration");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Start conversion
        config[1] |= ADS1115_CONFIG_OS_SINGLE;
        if (write(i2c_fd, config, 2) != 2) {
            perror("Failed to start conversion");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for conversion to complete
        usleep(250000); // 250 ms for 128 SPS

        // Read conversion result
        config[0] = ADS1115_REG_POINTER_CONVERT;
        if (write(i2c_fd, config, 1) != 1) {
            perror("Failed to set pointer to conversion register");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read conversion result");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Combine bytes into a 16-bit signed integer
        reading = (int16_t)(data[0] << 8 | data[1]);
        printf("Reading: %d\n", reading);

        // Wait before next reading
        usleep(200000); // 200 ms
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

