static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int state = 0;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the line for GPIO 4
    line = gpiod_chip_get_line(chip, 4);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO 4\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as a consumer
    ret = gpiod_line_request_output(line, "gpio4_control", state, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", gpiod_strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Toggle the state
        state = !state;
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", gpiod_strerror(-ret));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Report the state
        printf("GPIO 4 state set to: %d\n", state);

        // Wait for 60 seconds
        sleep(60);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

