volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    char filename[20];

    snprintf(filename, sizeof(filename), "/dev/i2c-%s", device);
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }

    return file;
}

int read_mpu6050(int file, int *accel_data) {
    char buffer[BUFFER_SIZE];
    if (read(file, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    accel_data[0] = (buffer[0] << 8) | buffer[1];
    accel_data[1] = (buffer[2] << 8) | buffer[3];
    accel_data[2] = (buffer[4] << 8) | buffer[5];

    return 0;
}

