#include <sys/ioctl.h>
#include <string.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x27 // Change this to your LCD's I2C address
#define LCD_WIDTH 16

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void i2c_write_byte(int file, uint8_t byte) {
    if (write(file, &byte, 1) != 1) {
        perror("Failed to write byte to I2C device");
        exit(EXIT_FAILURE);
    }
}

void lcd_send_command(int file, uint8_t command) {
    uint8_t data = command | 0x00; // RS = 0 for command
    i2c_write_byte(file, 0x80); // Enable RS and RW
    i2c_write_byte(file, data);
    usleep(4500); // Wait for command to be processed
}

void lcd_send_data(int file, uint8_t data) {
    uint8_t data_byte = data | 0x01; // RS = 1 for data
    i2c_write_byte(file, 0x80); // Enable RS and RW
    i2c_write_byte(file, data_byte);
    usleep(4500); // Wait for data to be processed
}

void lcd_init(int file) {
    lcd_send_command(file, 0x33); // Initialize
    lcd_send_command(file, 0x32); // Initialize
    lcd_send_command(file, 0x28); // 4-bit mode, 2 lines, 5x8 dots
    lcd_send_command(file, 0x0C); // Display on, cursor off
    lcd_send_command(file, 0x06); // Increment cursor
    lcd_send_command(file, 0x01); // Clear display
    usleep(2000); // Wait for clear to complete
}

void lcd_clear(int file) {
    lcd_send_command(file, 0x01); // Clear display
    usleep(2000); // Wait for clear to complete
}

void lcd_set_cursor(int file, uint8_t row, uint8_t col) {
    uint8_t address = (row == 0) ? 0x80 : 0xC0;
    address += col;
    lcd_send_command(file, address);
}

void lcd_print(int file, const char *str) {
    while (*str) {
        lcd_send_data(file, *str++);
    }
}

int main() {
    int file;
    struct sigaction sa;
    time_t start_time;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    file = open(I2C_DEVICE, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(file);
        return EXIT_FAILURE;
    }

    lcd_init(file);

    while (keep_running) {
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);

        char buffer[LCD_WIDTH + 1];
        strftime(buffer, sizeof(buffer), "%H:%M:%S", time_info);

        lcd_clear(file);
        lcd_set_cursor(file, 0, 0);
        lcd_print(file, buffer);

        sleep(10);
    }

    close(file);
    return EXIT_SUCCESS;
}

