#define TRIG_PIN 17
#define ECHO_PIN 22
#define MAX_DISTANCE_CM 400
#define TIMEOUT_US 1000000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    struct gpiod_line_event event;
    struct timespec ts_start, ts_end;
    long long duration_ns;
    double distance_cm;

    // Trigger the sensor
    gpiod_line_set_value(trig, 1);
    nanosleep((const struct timespec[]){{0, 10 * 1000 * 1000}}, NULL); // 10us
    gpiod_line_set_value(trig, 0);

    // Wait for echo start
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_RISING, TIMEOUT_US * 1000) < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        fprintf(stderr, "Failed to read echo start event\n");
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    // Wait for echo end
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_FALLING, TIMEOUT_US * 1000) < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &event) < 0) {
        fprintf(stderr, "Failed to read echo end event\n");
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    // Calculate duration
    duration_ns = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000LL + (ts_end.tv_nsec - ts_start.tv_nsec);

    // Calculate distance
    distance_cm = (duration_ns / 2.0) * 0.0343;

    return distance_cm;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    double distance_cm;

    // Setup signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get trigger line
    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(trig, "HC-SR04_trigger", GPIOD_LINE_REQUEST_DIRECTIONS_MASK) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get echo line
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo, "HC-SR04_echo", GPIOD_LINE_REQUEST_DIRECTIONS_MASK) < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        distance_cm = measure_distance(chip, trig, echo);
        if (distance_cm < 0) {
            fprintf(stderr, "Invalid reading\n");
        } else if (distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range\n");
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
        }
        usleep(100000); // Sleep for 0.1 seconds
    }

    // Cleanup
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

