#define DEVICE_ADDRESS 0x48      // Example I2C device address
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/reading"
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_QOS 1
#define MQTT_TIMEOUT 10000L

volatile sig_atomic_t stop = 0;

void signal_handler(int sig) {
    stop = 1;
}

int read_sensor_data(int fd, float *data) {
    char buffer[4];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from sensor");
        return -1;
    }
    *data = (buffer[0] << 8 | buffer[1]) / 100.0; // Example conversion
    return 0;
}

void cleanup(int fd, MQTTClient client) {
    if (fd >= 0) {
        close(fd);
    }
    MQTTClient_destroy(&client);
}

int main() {
    int i2c_fd = -1;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    float sensor_data;
    int rc;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(DEVICE_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        cleanup(i2c_fd, client);
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        cleanup(i2c_fd, client);
        return EXIT_FAILURE;
    }

    // Read sensor data
    if (read_sensor_data(i2c_fd, &sensor_data) != 0) {
        cleanup(i2c_fd, client);
        return EXIT_FAILURE;
    }

    // Publish sensor data
    char payload[50];
    snprintf(payload, sizeof(payload), "%f", sensor_data);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        cleanup(i2c_fd, client);
        return EXIT_FAILURE;
    }

    // Wait for message to be delivered
    MQTTClient_waitForCompletion(client, rc, MQTT_TIMEOUT);

    // Clean up
    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);
    cleanup(i2c_fd, client);

    return EXIT_SUCCESS;
}

