    gpio = gpioOpen(GPIO_PIN, 1);
    if (gpio < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    if (gpioSetPWMrange(gpio, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup(gpio);
        return 1;
    }

    // Main loop
