#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/readings"
#define MQTT_CLIENT_ID "ADS1115_Reader"
#define MQTT_QOS 1
#define MQTT_TIMEOUT 10000L

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd, ret;
    unsigned int value;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[50];

    // Setup signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        close(fd);
        return EXIT_FAILURE;
    }

    int reading_count = 0;
    while (keep_running && reading_count < 10) {
        // Write configuration to ADS1115
        uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                          ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
                          ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
        if (write(fd, &config, 2) != 2) {
            perror("Failed to write configuration to ADS1115");
            break;
        }

        // Read conversion result from ADS1115
        if (lseek(fd, ADS1115_REG_CONVERSION, SEEK_SET) == -1) {
            perror("Failed to seek to conversion register");
            break;
        }

        if (read(fd, &value, 2) != 2) {
            perror("Failed to read conversion result from ADS1115");
            break;
        }

        // Convert raw value to voltage
        float voltage = (value & 0x0FFF) * 6.144 / 32767.0;

        // Prepare MQTT message
        snprintf(payload, sizeof(payload), "Voltage: %.3f V", voltage);
        pubmsg.payload = payload;
        pubmsg.payloadlen = strlen(payload);
        pubmsg.qos = MQTT_QOS;
        pubmsg.retained = 0;

        // Publish message
        if (MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
            break;
        }

        // Wait for message to be delivered
        if (MQTTClient_waitForCompletion(client, token, MQTT_TIMEOUT) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
            break;
        }

        reading_count++;
        sleep(1); // Delay between readings
    }

    // Clean up
    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);
    close(fd);

    return EXIT_SUCCESS;
}

