    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        return;
    }

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("fopen");
        return;
    }

    if (fwrite(buffers[buf.index], 1, buffer_length[buf.index], file) != buffer_length[buf.index]) {
        perror("fwrite");
    }

    fclose(file);

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
    }
}

int main() {
    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        error_exit("Failed to open device");
