int read_mcp3008(gpiod_chip *chip, int channel) {
    gpiod_line *cs_line = gpiod_chip_get_line(chip, SPI_CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line\n");
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        fprintf(stderr, "Failed to request CS line\n");
        gpiod_line_release(cs_line);
        return -1;
    }

    uint8_t buffer[3] = {1, (8 + channel) << 4, 0};
    gpiod_line_set_value(cs_line, 0);

    usleep(1); // Ensure CS is low for at least 1us

    // SPI transfer
    if (ioctl(gpiod_line_get_fd(cs_line), SPI_IOC_MESSAGE(1), &buffer) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        gpiod_line_release(cs_line);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1);
    gpiod_line_release(cs_line);

    int value = ((buffer[1] & 3) << 8) | buffer[2];
    return value;
}

