#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;
    unsigned int echo_state;
    struct timespec ts;
    long duration_ns;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get trigger line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trig_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Set trigger high for 10us
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo to go high
        ret = gpiod_line_event_wait(echo_line, -1);
        if (ret < 0) {
            fprintf(stderr, "Echo line did not respond\n");
            break;
        }

        // Get the timestamp of the rising edge
        ret = gpiod_line_event_read(echo_line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo line event\n");
            break;
        }

        // Wait for echo to go low
        ret = gpiod_line_event_wait(echo_line, -1);
        if (ret < 0) {
            fprintf(stderr, "Echo line did not respond\n");
            break;
        }

        // Get the timestamp of the falling edge
        ret = gpiod_line_event_read(echo_line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo line event\n");
            break;
        }

        // Calculate duration
        duration_ns = ts.tv_sec * 1000000000 + ts.tv_nsec - ret.tv_sec * 1000000000 - ret.tv_nsec;

        // Calculate distance in cm (speed of sound is 34300 cm/s)
        double distance_cm = (duration_ns / 2.0) / 10000000.0;

        // Print the distance
        printf("Distance: %.2f cm\n", distance_cm);

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

