    char *buffers[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    FILE *output_file;
    char filename[32];
    while (keep_running) {
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                if (errno == EAGAIN) {
                    continue;
                } else {
                    perror("Failed to dequeue buffer");
                    break;
                }
            }

            snprintf(filename, sizeof(filename), "frame_%d.jpg", i);
            output_file = fopen(filename, "wb");
            if (!output_file) {
                perror("Failed to open output file");
                break;
            }

            if (fwrite(buffers[buf.index], 1, buf.bytesused, output_file) != buf.bytesused) {
                perror("Failed to write frame to file");
                fclose(output_file);
                break;
            }

            fclose(output_file);

            if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("Failed to queue buffer");
                break;
            }

            usleep(FRAME_INTERVAL);
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (munmap(buffers[i], buf.length) < 0) {
            perror("Failed to unmap buffer");
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

