#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400
#define TIMEOUT_US 1000000

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;
    uint64_t pulse_width_ns;
    uint64_t start_time, end_time;
    double distance_cm;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the trigger line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the trigger line as output
    ret = gpiod_line_request_output(trig_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the echo line as input with event detection
    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Send a 10us pulse to trigger the sensor
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    // Wait for the echo signal to start
    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_US);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for echo signal to start\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the start time
    start_time = gpiod_line_event_get_time(echo_line);

    // Wait for the echo signal to end
    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, TIMEOUT_US);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for echo signal to end\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the end time
    end_time = gpiod_line_event_get_time(echo_line);

    // Calculate the pulse width
    pulse_width_ns = end_time - start_time;

    // Calculate the distance in cm
    distance_cm = pulse_width_ns / 2.0 / 29.1;

    // Check if the distance is within the valid range
    if (distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Print the distance
    printf("Distance: %.2f cm\n", distance_cm);

    // Release resources
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

