#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define SHT31_MEASUREMENT_CMD 0x24
#define SHT31_MEASUREMENT_NOHOLD_CMD 0x2C
#define SHT31_READ_CMD 0xE3
#define SHT31_READ_NOHOLD_CMD 0xF3
#define SHT31_READ_STATUS_CMD 0xF32D
#define SHT31_READ_STATUS_REG 0x00
#define SHT31_READ_STATUS_BUSY 0x80

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int check_device_status(int file) {
    uint8_t status;
    if (ioctl(file, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(file, &SHT31_READ_STATUS_CMD, 2) != 2) {
        perror("Failed to write status command");
        return -1;
    }

    if (read(file, &status, 1) != 1) {
        perror("Failed to read status");
        return -1;
    }

    return (status & SHT31_READ_STATUS_BUSY) ? -1 : 0;
}

int read_measurement(int file, uint8_t *data, size_t len) {
    if (ioctl(file, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(file, &SHT31_MEASUREMENT_NOHOLD_CMD, 1) != 1) {
        perror("Failed to write measurement command");
        return -1;
    }

    if (check_device_status(file) != 0) {
        fprintf(stderr, "Device is busy\n");
        return -1;
    }

    usleep(10000); // Wait for measurement to complete

    if (write(file, &SHT31_READ_NOHOLD_CMD, 1) != 1) {
        perror("Failed to write read command");
        return -1;
    }

    if (read(file, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int main() {
    int file;
    uint8_t data[3];
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        return EXIT_FAILURE;
    }

    file = open(I2C_DEVICE, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(file);
        return EXIT_FAILURE;
    }

    if (write(file, &SHT31_MEASUREMENT_CMD, 1) != 1) {
        perror("Failed to write measurement command");
        close(file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_measurement(file, data, 3) == 0) {
            int16_t raw_temp = (data[0] << 8) | data[1];
            int16_t raw_hum = (data[2] << 8) | (data[3] & 0xFF);

            float temperature = -45 + 175 * (raw_temp / 65535.0);
            float humidity = 100 * (raw_hum / 65535.0);

            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read measurement\n");
        }

        sleep(5);
    }

    close(file);
    return EXIT_SUCCESS;
}

