#define GPIO_22 22
#define GPIO_27 27

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio daemon not running\n");
        return 1;
    }

    int gpios[] = {GPIO_17, GPIO_18, GPIO_22, GPIO_27};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);
    int pwm_handle[num_gpios];
    int frequency = 1000; // 1 kHz
    int duty_cycle = 512; // 50% duty cycle

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output\n", gpios[i]);
            gpioTerminate();
            return 1;
        }

        pwm_handle[i] = gpioServo(gpios[i], 0);
        if (pwm_handle[i] < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
    }

    for (int i = 0; i < num_gpios; i++) {
        if (gpioPWM(gpios[i], frequency, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
        printf("GPIO %d: PWM set to frequency %d Hz, duty cycle %d\n", gpios[i], frequency, duty_cycle);
    }

    // Clean up
    for (int i = 0; i < num_gpios; i++) {
        gpioPWM(gpios[i], 0, 0); // Stop PWM
        gpioServo(gpios[i], 0);  // Release PWM
    }

    gpioTerminate();
    return 0;
}

