#define DEVICE_PATH "/sys/bus/w1/devices/"
#define DS18B20_FAMILY_CODE "28-"
#define MAX_DEVICE_PATH_LENGTH 256
#define MAX_TEMP_STRING_LENGTH 6

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    char device_path[MAX_DEVICE_PATH_LENGTH];
    FILE *device_file = NULL;
    char temp_string[MAX_TEMP_STRING_LENGTH];
    int readings = 0;
    int found_device = 0;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the directory containing the 1-Wire devices
    DIR *dir = opendir(DEVICE_PATH);
    if (!dir) {
        perror("Failed to open device directory");
        return EXIT_FAILURE;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, DS18B20_FAMILY_CODE, strlen(DS18B20_FAMILY_CODE)) == 0) {
            snprintf(device_path, sizeof(device_path), "%s%s/w1_slave", DEVICE_PATH, entry->d_name);
            found_device = 1;
            break;
        }
    }

    closedir(dir);

    if (!found_device) {
        fprintf(stderr, "DS18B20 device not found\n");
        return EXIT_FAILURE;
    }

    while (keep_running && readings < 3) {
        // Open the device file
        device_file = fopen(device_path, "r");
        if (!device_file) {
            perror("Failed to open device file");
            return EXIT_FAILURE;
        }

        // Read the temperature from the device
        if (fgets(temp_string, sizeof(temp_string), device_file) == NULL) {
            perror("Failed to read temperature");
            fclose(device_file);
            return EXIT_FAILURE;
        }

        if (fgets(temp_string, sizeof(temp_string), device_file) == NULL) {
            perror("Failed to read temperature");
            fclose(device_file);
            return EXIT_FAILURE;
        }

        fclose(device_file);

        // Find the position of the '=' character
        char *equal_pos = strchr(temp_string, '=');
        if (!equal_pos) {
            fprintf(stderr, "Failed to find temperature value\n");
            return EXIT_FAILURE;
        }

        // Extract the temperature value
        char temp_value[MAX_TEMP_STRING_LENGTH];
        strncpy(temp_value, equal_pos + 1, sizeof(temp_value) - 1);
        temp_value[sizeof(temp_value) - 1] = '\0';

        // Convert the temperature to a float
        float temperature = atof(temp_value) / 1000.0;
        printf("Temperature: %.2f°C\n", temperature);

        readings++;
        if (readings < 3) {
            sleep(5);
        }
    }

    return EXIT_SUCCESS;
}

