int setup_gpio(int gpio, int frequency, int duty_cycle) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", gpio);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(gpio, frequency, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpio);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup_gpio(int gpio) {
    gpioPWM(gpio, 0, 0); // Stop PWM
    gpioTerminate();
}

