int read_dht22(gpiod_line_handle_t line) {
    uint64_t data = 0;
    int ret;
    int bit_idx = 0;
    int last_level = 0;
    int level;
    int count = 0;
    int max_count = 1000000; // Timeout count

    // Start signal
    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output: %s\n", strerror(-ret));
        return -1;
    }

    // Send start signal
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line value: %s\n", strerror(-ret));
        return -1;
    }
    usleep(18000); // 18ms

    // Release the line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to release line: %s\n", strerror(-ret));
        return -1;
    }

    // Request input
    ret = gpiod_line_request_input(line, "dht22", GPIOD_LINE_REQ_DIR_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request input: %s\n", strerror(-ret));
        return -1;
    }

    // Wait for response
    ret = gpiod_line_get_value(line, &level);
    if (ret < 0) {
        fprintf(stderr, "Failed to get line value: %s\n", strerror(-ret));
        return -1;
    }

    if (level != 0) {
        fprintf(stderr, "DHT22 did not pull line low\n");
        return -1;
    }

    // Wait for the pin to go high
    while (level == 0) {
        ret = gpiod_line_get_value(line, &level);
        if (ret < 0) {
            fprintf(stderr, "Failed to get line value: %s\n", strerror(-ret));
            return -1;
        }
        if (++count > max_count) {
            fprintf(stderr, "Timeout waiting for DHT22 response\n");
            return -1;
        }
    }

    // Wait for the pin to go low
    count = 0;
    while (level == 1) {
        ret = gpiod_line_get_value(line, &level);
        if (ret < 0) {
            fprintf(stderr, "Failed to get line value: %s\n", strerror(-ret));
            return -1;
        }
        if (++count > max_count) {
            fprintf(stderr, "Timeout waiting for DHT22 response\n");
            return -1;
        }
    }

    // Read 40 bits of data
    for (int i = 0; i < 40; i++) {
        // Wait for the pin to go high
        count = 0;
        while (level == 0) {
            ret = gpiod_line_get_value(line, &level);
            if (ret < 0) {
                fprintf(stderr, "Failed to get line value: %s\n", strerror(-ret));
                return -1;
            }
            if (++count > max_count) {
                fprintf(stderr, "Timeout waiting for DHT22 data\n");
                return -1;
            }
        }

        // Measure the length of the high pulse
        count = 0;
        while (level == 1) {
            ret = gpiod_line_get_value(line, &level);
            if (ret < 0) {
                fprintf(stderr, "Failed to get line value: %s\n", strerror(-ret));
                return -1;
            }
            if (++count > max_count) {
                fprintf(stderr, "Timeout waiting for DHT22 data\n");
                return -1;
            }
        }

        // Determine the bit value
        if (count > 16) {
            data |= (1ULL << bit_idx);
        }
        bit_idx++;
    }

    // Validate checksum
    uint8_t checksum = (data & 0xFF);
    uint8_t sum = ((data >> 8) & 0xFF) + ((data >> 16) & 0xFF) + ((data >> 24) & 0xFF);
    if (checksum != (sum & 0xFF)) {
        fprintf(stderr, "Checksum failed\n");
        return -1;
    }

    // Extract humidity and temperature
    uint8_t humidity = (data >> 8) & 0xFF;
    uint8_t temperature = (data >> 16) & 0xFF;

    printf("Humidity: %.1f%%, Temperature: %.1fC\n", humidity / 10.0, temperature / 10.0);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    gpiod_line_handle_t line_handle;
    int ret;

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get line
    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Convert to line handle
    line_handle = gpiod_line_get(line);
    if (!line_handle) {
        fprintf(stderr, "Failed to get line handle\n");
        gpiod_chip_put_line(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Perform DHT22 readings
    for (int i = 0; i < DHT22_MAX_CYCLES && !interrupted; i++) {
        ret = read_dht22(line_handle);
        if (ret < 0) {
            fprintf(stderr, "Failed to read DHT22\n");
            break;
        }
    }

    // Release resources
    gpiod_line_release(line_handle);
    gpiod_chip_put_line(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

