#define DELAY 0.5

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_GPIO_PINS];
    int line_offset[] = GPIO_PINS;
    int ret, i;

    // Set up signal handler to handle interrupts
    signal(SIGINT, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < NUM_GPIO_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offset[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", line_offset[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
