            fprintf(stderr, "Failed to request line %d as output\n", line_offset[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Perform cycles
    for (int cycle = 0; cycle < CYCLES && keep_running; cycle++) {
        for (i = 0; i < NUM_GPIO_PINS; i++) {
            ret = gpiod_line_set_value(lines[i], cycle % 2);
