#define GPIO_PINS {17, 18, 22, 23, 24, 25}
#define PWM_RANGE 255
#define PWM_FREQUENCY 1000
#define DELAY 50 // milliseconds

static int gpios[] = GPIO_PINS;
static int num_gpios = sizeof(gpios) / sizeof(gpios[0]);
static int pi = -1;
static int pwm_handles[num_gpios];

void cleanup(int signum) {
    for (int i = 0; i < num_gpios; i++) {
        if (pwm_handles[i] != -1) {
            gpioPWMStop(pi, pwm_handles[i]);
            gpioSetPWMrange(pi, pwm_handles[i], 0);
        }
    }
    if (pi != -1) {
        gpioTerminate(pi);
    }
    exit(0);
}

int main() {
    int i, pwm_value = 0, increment = 1;

    // Set up signal handler for clean exit
    signal(SIGINT, cleanup);

    // Initialize pigpio
    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio daemon\n");
        return 1;
    }

    // Set up PWM for each GPIO
    for (i = 0; i < num_gpios; i++) {
        if (gpioSetMode(pi, gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output\n", gpios[i]);
            cleanup(0);
        }
        if (gpioSetPWMfrequency(pi, gpios[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpios[i]);
            cleanup(0);
        }
        if (gpioSetPWMrange(pi, gpios[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", gpios[i]);
            cleanup(0);
        }
        pwm_handles[i] = gpioCreatePWM(pi, gpios[i]);
        if (pwm_handles[i] < 0) {
            fprintf(stderr, "Failed to create PWM for GPIO %d\n", gpios[i]);
            cleanup(0);
        }
    }

    // Main loop
    while (1) {
        for (i = 0; i < num_gpios; i++) {
            if (gpioPWM(pwm_handles[i], pwm_value) < 0) {
                fprintf(stderr, "Failed to set PWM value for GPIO %d\n", gpios[i]);
                cleanup(0);
            }
        }

        // Print the current PWM value
        printf("PWM Value: %d\n", pwm_value);

        // Update PWM value
        pwm_value += increment;
        if (pwm_value > PWM_RANGE) {
            pwm_value = PWM_RANGE;
            increment = -1;
        } else if (pwm_value < 0) {
            pwm_value = 0;
            increment = 1;
        }

        // Wait for the next cycle
        usleep(DELAY * 1000);
    }

    // Cleanup should not be reached, but just in case
    cleanup(0);
    return 0;
}

