#include <gpiod.h>

#define DHT22_GPIO_PIN 4
#define DHT22_GPIO_LINE 17
#define DHT22_MAX_CYCLES 3
#define DHT22_TIMEOUT_USEC 1000000 // 1 second

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int read_dht22(gpiod_line_handle_t line) {
    uint64_t data = 0;
    int ret;
    uint8_t bits[5] = {0};
    int bit_idx = 0;
    int byte_idx = 0;

    // Set GPIO as output
    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO as output: %s\n", strerror(-ret));
        return -1;
    }

    // Send start signal
    usleep(18000); // 18ms
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO low: %s\n", strerror(-ret));
        return -1;
    }
    usleep(20000); // 20-40us
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO high: %s\n", strerror(-ret));
        return -1;
    }
    usleep(40); // 40us

    // Set GPIO as input
    ret = gpiod_line_request_input(line, "dht22", GPIOD_LINE_REQ_DIR_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO as input: %s\n", strerror(-ret));
        return -1;
    }

    // Wait for response
    ret = gpiod_line_event_wait(line, DHT22_TIMEOUT_USEC);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for DHT22 response: %s\n", strerror(-ret));
        return -1;
    }

    // Read 40 bits
    for (int i = 0; i < 40; i++) {
        ret = gpiod_line_event_wait(line, DHT22_TIMEOUT_USEC);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for DHT22 bit: %s\n", strerror(-ret));
            return -1;
        }

        uint64_t value;
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO value: %s\n", strerror(-ret));
            return -1;
        }

        if (value == 1) {
            usleep(50); // Wait for end of high pulse
            ret = gpiod_line_event_wait(line, DHT22_TIMEOUT_USEC);
            if (ret < 0) {
                fprintf(stderr, "Timeout waiting for DHT22 bit end: %s\n", strerror(-ret));
                return -1;
            }

            uint64_t value_end;
            ret = gpiod_line_get_value(line, &value_end);
            if (ret < 0) {
                fprintf(stderr, "Failed to read GPIO value end: %s\n", strerror(-ret));
                return -1;
            }

            if (value_end == 0) {
                bits[byte_idx] |= (1 << (7 - bit_idx));
            }
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    // Validate checksum
    if ((bits[0] + bits[1] + bits[2] + bits[3]) & 0xFF) {
        fprintf(stderr, "DHT22 checksum failed\n");
        return -1;
    }

    // Print humidity and temperature
    printf("Humidity: %d.%d%%, Temperature: %d.%d°C\n",
           bits[0], bits[1], bits[2], bits[3]);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    gpiod_line_handle_t line_handle;
    int ret;

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get line
    line = gpiod_chip_get_line(chip, DHT22_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    line_handle = gpiod_line_request(line, "dht22", GPIOD_LINE_REQUEST_DIRECTIONS_NONE);
    if (!line_handle) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(-gpiod_line_request_error(line)));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Perform DHT22 readings
    for (int i = 0; i < DHT22_MAX_CYCLES && !stop; i++) {
        ret = read_dht22(line_handle);
        if (ret < 0) {
            fprintf(stderr, "Failed to read DHT22\n");
            break;
        }
        sleep(60);
    }

    // Release resources
    gpiod_line_release(line_handle);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

