        lines[i] = gpiod_chip_get_line(chip, GPIO_NUMBERS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_NUMBERS[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "gpio_control", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d\n", GPIO_NUMBERS[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    // Perform cycles
    for (int cycle = 0; cycle < CYCLES && keep_running; cycle++) {
        for (i = 0; i < NUM_GPIO; i++) {
            ret = gpiod_line_set_value(lines[i], cycle % 2);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value on line %d\n", GPIO_NUMBERS[i]);
