    for (i = 0; i < NUM_GPIO; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret == EXIT_FAILURE ? EXIT_FAILURE : EXIT_SUCCESS;
}

