#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 500000

#define MAX31855_READ 0x80
#define MAX31855_CONFIG 0x60
#define MAX31855_CR0 0x00
#define MAX31855_CR1 0x01
#define MAX31855_FAULT 0x07
#define MAX31855_TEMP 0x05

#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_SHORT_TO_VCC 0x02
#define MAX31855_FAULT_SHORT_TO_GND 0x04

int spi_fd = -1;

void close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int init_spi() {
    struct spi_ioc_transfer transfer;
    uint8_t tx[] = { MAX31855_READ | MAX31855_TEMP, 0 };
    uint8_t rx[3] = { 0 };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close_spi();
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close_spi();
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to set SPI max speed");
        close_spi();
        return -1;
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = sizeof(tx);
    transfer.delay_usecs = 0;
    transfer.speed_hz = SPI_MAX_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to perform SPI transfer");
        close_spi();
        return -1;
    }

    return 0;
}

int read_max31855(float *temperature) {
    uint8_t tx[] = { MAX31855_READ | MAX31855_TEMP, 0 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer transfer;
    uint16_t raw_temp;
    int16_t fault_status;

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = sizeof(tx);
    transfer.delay_usecs = 0;
    transfer.speed_hz = SPI_MAX_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    raw_temp = (rx[0] << 8) | rx[1];
    fault_status = (rx[2] & 0x1F);

    if (fault_status & MAX31855_FAULT_OPEN) {
        fprintf(stderr, "Fault: Open circuit detected\n");
        return -1;
    }
    if (fault_status & MAX31855_FAULT_SHORT_TO_VCC) {
        fprintf(stderr, "Fault: Short to VCC detected\n");
        return -1;
    }
    if (fault_status & MAX31855_FAULT_SHORT_TO_GND) {
        fprintf(stderr, "Fault: Short to GND detected\n");
        return -1;
    }

    *temperature = (raw_temp & 0xFFF) * 0.25;
    if (raw_temp & 0x1000) {
        *temperature = -((~raw_temp & 0xFFF) + 1) * 0.25;
    }

    return 0;
}

int main() {
    float temperature;

    if (init_spi() < 0) {
        fprintf(stderr, "Error initializing SPI\n");
        return EXIT_FAILURE;
    }

    if (read_max31855(&temperature) < 0) {
        fprintf(stderr, "Error reading MAX31855\n");
        close_spi();
        return EXIT_FAILURE;
    }

    printf("Temperature: %.2f°C\n", temperature);

    close_spi();
    return EXIT_SUCCESS;
}

