#include <time.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define MAX_WAIT_US 1000000 // 1 second

volatile sig_atomic_t interrupted = 0;

void handle_signal(int sig) {
    interrupted = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    struct gpiod_line_request req;
    struct timespec start, end;
    long duration_ns;
    double distance_cm;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines for trigger and echo
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trig_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set trigger line to low
    gpiod_line_set_value(trig_line, 0);

    // Send pulse
    gpiod_line_set_value(trig_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trig_line, 0);

    // Wait for echo start
    ret = gpiod_line_event_wait(echo_line, MAX_WAIT_US);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get start time
    ret = gpiod_line_event_get(echo_line, &start);
    if (ret < 0) {
        fprintf(stderr, "Failed to get start time: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Wait for echo end
    ret = gpiod_line_event_wait(echo_line, MAX_WAIT_US);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get end time
    ret = gpiod_line_event_get(echo_line, &end);
    if (ret < 0) {
        fprintf(stderr, "Failed to get end time: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Calculate duration
    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    // Calculate distance
    distance_cm = (duration_ns / 2.0) * 0.0343;

    // Output the distance
    printf("Distance: %.2f cm\n", distance_cm);

    // Release resources
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

