#define BMP280_REGISTER_TEMP_MSB 0xFA

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_i2c_byte(int file, uint8_t reg) {
    if (ioctl(file, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    uint8_t data;
    if (read(file, &data, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return data;
}

int read_bmp280_measurement(int file) {
    uint8_t msb, lsb, xlsb;
    int32_t raw_pressure, raw_temperature;

    msb = read_i2c_byte(file, BMP280_REGISTER_PRESSURE_MSB);
    lsb = read_i2c_byte(file, BMP280_REGISTER_PRESSURE_MSB + 1);
    xlsb = read_i2c_byte(file, BMP280_REGISTER_PRESSURE_MSB + 2);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        return -1;
    }

    raw_pressure = ((int32_t)msb << 12) | ((int32_t)lsb << 4) | (xlsb >> 4);

    msb = read_i2c_byte(file, BMP280_REGISTER_TEMP_MSB);
    lsb = read_i2c_byte(file, BMP280_REGISTER_TEMP_MSB + 1);
    xlsb = read_i2c_byte(file, BMP280_REGISTER_TEMP_MSB + 2);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        return -1;
    }

    raw_temperature = ((int32_t)msb << 12) | ((int32_t)lsb << 4) | (xlsb >> 4);

    printf("Raw Pressure: %ld, Raw Temperature: %ld\n", raw_pressure, raw_temperature);
    return 0;
}

