    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    file = open(I2C_DEVICE, O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
