int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("Failed to open UART device");
        return -1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) < 0) {
        perror("Failed to get UART attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;

    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 1;
    options.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("Failed to set UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, handle_signal);

    int uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    fd_set read_fds;
    struct timeval timeout;
    char buffer[256];
    ssize_t bytes_read;

    while (keep_running) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

        int select_result = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (select_result < 0) {
            perror("Select error");
            break;
        } else if (select_result == 0) {
            // Timeout occurred, no data available
            continue;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
            if (bytes_read < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    // No data available, continue
                    continue;
                } else {
                    perror("Read error");
                    break;
                }
            } else if (bytes_read == 0) {
                // Device disconnected
                fprintf(stderr, "Device disconnected\n");
                break;
            }

            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        }
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

