double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    struct gpiod_line_event event;
    struct gpiod_line_request req;
    struct gpiod_line_event event_echo;
    struct gpiod_line_request req_echo;
    struct gpiod_line_event event_timeout;
    struct gpiod_line_request req_timeout;
    struct gpiod_line_event event_timeout_echo;
    struct gpiod_line_request req_timeout_echo;
    uint64_t ts_start, ts_end;
    double distance_cm;

    // Request event for echo pin
    if (gpiod_line_request_events(echo, "echo_event", GPIOD_LINE_REQ_EV_FALLING | GPIOD_LINE_REQ_EV_RISING, &req_echo) < 0) {
        fprintf(stderr, "Failed to request events for echo pin\n");
        return -1;
    }

    // Request event for timeout
    if (gpiod_line_request_timeout(echo, "timeout_event", TIMEOUT_US, &req_timeout) < 0) {
        fprintf(stderr, "Failed to request timeout for echo pin\n");
        gpiod_line_release(req_echo.line);
        return -1;
    }

    // Trigger the sensor
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger pin high\n");
        gpiod_line_release(req_echo.line);
        gpiod_line_release(req_timeout.line);
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger pin low\n");
        gpiod_line_release(req_echo.line);
        gpiod_line_release(req_timeout.line);
        return -1;
    }

    // Wait for echo start event
    if (gpiod_line_event_wait(req_echo.line, &event_echo, -1) < 0) {
        fprintf(stderr, "Failed to wait for echo start event\n");
        gpiod_line_release(req_echo.line);
        gpiod_line_release(req_timeout.line);
        return -1;
    }
    ts_start = event_echo.ts.tv_sec * 1000000 + event_echo.ts.tv_nsec / 1000;

    // Wait for echo end event or timeout
    if (gpiod_line_event_wait(req_timeout.line, &event_timeout, -1) < 0) {
        fprintf(stderr, "Failed to wait for echo end event or timeout\n");
        gpiod_line_release(req_echo.line);
        gpiod_line_release(req_timeout.line);
        return -1;
    }

    if (event_timeout.type == GPIOD_LINE_EVENT_TIMEOUT) {
        fprintf(stderr, "Timeout occurred\n");
        gpiod_line_release(req_echo.line);
        gpiod_line_release(req_timeout.line);
        return -1;
    }

    ts_end = event_timeout.ts.tv_sec * 1000000 + event_timeout.ts.tv_nsec / 1000;

    // Calculate distance
    distance_cm = (ts_end - ts_start) / 58.0;

    // Release resources
    gpiod_line_release(req_echo.line);
    gpiod_line_release(req_timeout.line);

    return distance_cm;
}

