    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;
    unsigned long long pulse_start, pulse_end, pulse_duration;
    float distance_cm;

    // Register signal handler for graceful exit
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get trigger line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trig_line, "trigger", 0);
    if (ret < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set trigger line to low
    gpiod_line_set_value(trig_line, 0);
    usleep(2 * 1000); // 2ms delay

    // Send 10us pulse
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    // Wait for echo start
    ret = gpiod_line_event_wait(echo_line, -1);
    if (ret < 0) {
        perror("Failed to wait for echo start");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
