#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    char *i2c_device_path = I2C_DEVICE;
    uint8_t buffer[4];
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open I2C device
    i2c_fd = open(i2c_device_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if device is present
    ret = read(i2c_fd, buffer, 1);
    if (ret < 0) {
        if (errno == ENXIO) {
            fprintf(stderr, "TCS34725 not found at address 0x%02X\n", TCS34725_ADDRESS);
            close(i2c_fd);
            return EXIT_FAILURE;
        } else {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (keep_running) {
        // Read data from TCS34725
        ret = read(i2c_fd, buffer, 4);
        if (ret < 0) {
            perror("Failed to read from TCS34725");
            break;
        }

        // Print the readings
        printf("R: %d, G: %d, B: %d, Clear: %d\n",
               buffer[0] << 8 | buffer[1],
               buffer[2] << 8 | buffer[3],
               0, 0); // Assuming clear channel is not implemented

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

