#define TRIG_PIN 18
#define ECHO_PIN 23
#define TIMEOUT_USEC 1000000 // 1 second timeout

volatile sig_atomic_t interrupted = 0;

void handle_signal(int sig) {
    interrupted = 1;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    long duration;
    double distance;

    // Set trigger pin to low
    gpiod_line_set_value(trig, 0);
    usleep(2);

    // Send 10us pulse
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);

    // Wait for echo pin to go high
    if (gpiod_line_get_value(echo) == 1) {
        return -1; // Echo pin already high, invalid state
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        perror("clock_gettime");
        return -1;
    }

    while (gpiod_line_get_value(echo) == 0) {
        if (interrupted) {
            return -1; // Interrupted
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
        perror("clock_gettime");
        return -1;
    }

    duration = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    if (duration > TIMEOUT_USEC * 1000) {
        return -1; // Timeout
    }

    // Wait for echo pin to go low
    while (gpiod_line_get_value(echo) == 1) {
        if (interrupted) {
            return -1; // Interrupted
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
        perror("clock_gettime");
        return -1;
    }

    duration = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    if (duration > TIMEOUT_USEC * 1000) {
        return -1; // Timeout
    }

    // Calculate distance
    distance = (duration / 2.0) * 0.0343; // Speed of sound in cm/us
    return distance;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    double distance;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Get trigger line
    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    if (gpiod_line_request_output(trig, "trigger", 0)) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get echo line
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

