    if (gpiod_line_request_input(echo, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        perror("gpiod_line_request_input");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Measure distance
