    if (distance < 0) {
        fprintf(stderr, "Failed to measure distance\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }

    // Release resources
    gpiod_line_release(echo);
    gpiod_line_release(trig);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

