        if (nanosleep((const struct timespec[]){{0, INTERVAL}}, NULL) != 0) {
            fprintf(stderr, "Failed to sleep\n");
            break;
        }
    }

    gpioPWM(GPIO_PIN, 0, 0); // Stop PWM
    gpioTerminate();

    printf("Exiting cleanly\n");
    return EXIT_SUCCESS;
}

